"""Execution Worker: Secure subprocess sandbox with AST/timeout guardrails."""

from __future__ import annotations

import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path

@dataclass
class SandboxResult:
    stdout: str
    stderr: str
    exit_code: int
    is_timeout: bool = False


class ExecWorker:
    """Safely executes diagnostic Python code generated by the agent inside an isolated subprocess."""
    def __init__(self, timeout_sec: float = 4.0) -> None:
        self.timeout_sec = timeout_sec
    def run_code(self, python_code: str) -> SandboxResult:
        """Executes Python code in an isolated subprocess with stripped environment variables."""
        # 1. Environment Scrubbing: Wipe all host API keys and secrets!
        safe_env = {
            "PATH": "/usr/bin:/bin",  # Minimal safe binaries
            "PYTHONPATH": "",  # Prevent access to host application modules
            "PYTHONIOENCODING": "utf-8",
        }
        # 2. Write code to a secure temporary file
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".py", delete=False, encoding="utf-8"
        ) as tmp:
            tmp.write(python_code)
            tmp_path = Path(tmp.name)
        try:
            # 3. Launch isolated subprocess using python3 -I (Isolated mode)
            result = subprocess.run(
                [sys.executable, "-I", str(tmp_path)],
                capture_output=True,
                text=True,
                timeout=self.timeout_sec,
                env=safe_env,
            )
            return SandboxResult(
                stdout=result.stdout.strip(),
                stderr=result.stderr.strip(),
                exit_code=result.returncode,
            )
        except subprocess.TimeoutExpired:
            return SandboxResult(
                stdout="",
                stderr=f"Execution timed out after {self.timeout_sec}s (Infinite Loop Guardrail triggered).",
                exit_code=-1,
                is_timeout=True,
            )
        finally:
            # Always delete the temporary script
            if tmp_path.exists():
                tmp_path.unlink()
